package android.app;import android.content.*;public class PendingIntent{public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2,FLAG_MUTABLE=4;public Intent intent;public int flags;public static PendingIntent getActivity(Context c,int i,Intent v,int f){return getService(c,i,v,f);}public static PendingIntent getService(Context c,int i,Intent v,int f){PendingIntent p=new PendingIntent();p.intent=v;p.flags=f;return p;}}